class EventArgs:
    """Event data passed to handlers: X, Y, Button, Delta, KeyCode, KeyChar, Cancel."""

    def __init__(self, ev=None):
        self.raw = ev
        self.X = self.Y = self.Delta = 0
        self.Button = 0
        self.KeyCode = 0
        self.KeyChar = ""
        self.Cancel = False
        if ev is None:
            return
        if hasattr(ev, "position"):
            p = ev.position()
            self.X, self.Y = int(p.x()), int(p.y())
        if hasattr(ev, "button"):
            self.Button = {Qt.MouseButton.LeftButton: 1, Qt.MouseButton.MiddleButton: 2,
                           Qt.MouseButton.RightButton: 3}.get(ev.button(), 0)
        if hasattr(ev, "angleDelta"):
            self.Delta = ev.angleDelta().y()
        if hasattr(ev, "key"):
            self.KeyCode = ev.key()
            self.KeyChar = ev.text()


class _Events(QObject):
    """Event filter that routes Qt events to VB-style handlers."""

    def __init__(self, owner, widget, table):
        super().__init__(widget)
        self.owner, self.table = owner, table      # {QEvent.Type: [(handler, kind, chars_only)]}
        widget.installEventFilter(self)

    def eventFilter(self, obj, ev):
        for name, kind, chars in self.table.get(ev.type(), ()):
            if chars and not ev.text():
                continue
            fn = getattr(self.owner, name, None)
            if fn is not None:
                fn(EventArgs(ev)) if kind else fn()
        return False

class _Layout(QObject):
    """Anchor / Dock: re-places the children of *host* whenever it is resized.
    spec = (x, y, w, h, rx, ry, rw, rh): x = x0 + rx * host width, width = w0 + rw * host width..."""

    def __init__(self, host):
        super().__init__(host)
        self.host, self.items = host, []
        host.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.host and ev.type() == QEvent.Type.Resize:
            self.apply()
        return False

    def apply(self):
        cw, ch = self.host.width(), self.host.height()
        for w, (x, y, ww, hh, rx, ry, rw, rh) in self.items:
            g = [round(x + rx * cw), round(y + ry * ch), max(0, round(ww + rw * cw)), max(0, round(hh + rh * ch))]
            held = getattr(w, "_rad_held", None)    # geometry a visual state / storyboard is animating
            if held:
                for i, (prop, cur) in enumerate((("Left", w.x()), ("Top", w.y()), ("Width", w.width()),
                                                 ("Height", w.height()))):
                    if prop in held:
                        g[i] = cur
            w.setGeometry(*g)


def _place(widget, host, spec):
    lay = host.findChild(_Layout, "", Qt.FindChildOption.FindDirectChildrenOnly)
    if lay is None:
        lay = _Layout(host)
    lay.items.append((widget, spec))

def _fill_tree(tree, nodes):
    """nodes = [(path, text), ...] with parents first ("Root", "Root/Child")."""
    items = {}
    for path, text in nodes:
        parent = items.get(path.rpartition("/")[0])
        item = QTreeWidgetItem([text])
        if parent is None:
            tree.addTopLevelItem(item)
        else:
            parent.addChild(item)
        items[path] = item
    tree.expandAll()


def _fill_table(table, columns, rows):
    table.setColumnCount(max([len(columns)] + [len(r) for r in rows]))
    table.setHorizontalHeaderLabels(columns)
    table.setRowCount(len(rows))
    for r, row in enumerate(rows):
        for c, text in enumerate(row):
            table.setItem(r, c, QTableWidgetItem(text))

def _qt_filter(value):
    """'Text files|*.txt|All|*.*' -> 'Text files (*.txt);;All (*.*)'."""
    parts = [p.strip() for p in str(value or "").split("|")]
    pairs = [f"{parts[i]} ({parts[i + 1].replace(';', ' ')})" for i in range(0, len(parts) - 1, 2)]
    return ";;".join(pairs) or "All files (*.*)"


class _FileDialog:
    """OpenFileDialog / SaveFileDialog: ShowDialog() returns "OK" or "Cancel" and sets FileName."""

    def __init__(self, parent, save=False, Title="", Filter="", FileName="", InitialDirectory=""):
        self._parent, self._save = parent, save
        self.Title, self.Filter, self.FileName, self.InitialDirectory = Title, Filter, FileName, InitialDirectory

    def ShowDialog(self):
        start = self.InitialDirectory or (os.path.dirname(self.FileName) if self.FileName else "")
        dlg = QFileDialog(self._parent, self.Title, start, _qt_filter(self.Filter))
        if self._save:
            dlg.setAcceptMode(QFileDialog.AcceptMode.AcceptSave)
            dlg.setFileMode(QFileDialog.FileMode.AnyFile)
        else:
            dlg.setFileMode(QFileDialog.FileMode.ExistingFile)
        if self.FileName:
            dlg.selectFile(self.FileName)
        ok = dlg.exec() == QDialog.DialogCode.Accepted and dlg.selectedFiles()
        if ok:
            self.FileName = dlg.selectedFiles()[0]
        dlg.deleteLater()
        return "OK" if ok else "Cancel"


class _FolderDialog:
    """FolderBrowserDialog: ShowDialog() returns "OK" or "Cancel" and sets SelectedPath."""

    def __init__(self, parent, SelectedPath=""):
        self._parent, self.SelectedPath = parent, SelectedPath
        self.Title = "Select Folder"

    def ShowDialog(self):
        dlg = QFileDialog(self._parent, self.Title, self.SelectedPath)
        dlg.setFileMode(QFileDialog.FileMode.Directory)
        dlg.setOption(QFileDialog.Option.ShowDirsOnly, True)
        ok = dlg.exec() == QDialog.DialogCode.Accepted and dlg.selectedFiles()
        if ok:
            self.SelectedPath = dlg.selectedFiles()[0]
        dlg.deleteLater()
        return "OK" if ok else "Cancel"


class _ColorDialog:
    """ColorDialog: ShowDialog() returns "OK" or "Cancel" and sets Color ("#rrggbb")."""

    def __init__(self, parent, Color="#000000"):
        self._parent, self.Color = parent, Color

    def ShowDialog(self):
        dlg = QColorDialog(QColor(self.Color or "#000000"), self._parent)
        ok = dlg.exec() == QDialog.DialogCode.Accepted
        if ok:
            self.Color = dlg.selectedColor().name()
        dlg.deleteLater()
        return "OK" if ok else "Cancel"


class _FontDialog:
    """FontDialog: ShowDialog() returns "OK" or "Cancel" and sets FontName / FontSize."""

    def __init__(self, parent, FontName="Segoe UI", FontSize=9):
        self._parent, self.FontName, self.FontSize = parent, FontName, FontSize

    def ShowDialog(self):
        dlg = QFontDialog(QFont(self.FontName, int(self.FontSize or 9)), self._parent)
        ok = dlg.exec() == QDialog.DialogCode.Accepted
        if ok:
            f = dlg.selectedFont()
            self.FontName, self.FontSize = f.family(), f.pointSize()
        dlg.deleteLater()
        return "OK" if ok else "Cancel"


